import React from 'react';
// @ts-ignore
import Plotly from 'plotly.js-dist-min';
import createPlotlyComponent from 'react-plotly.js/factory';
import { Loader2, AlertCircle } from 'lucide-react';

const Plot = createPlotlyComponent(Plotly);

interface HSVPoint {
  hsv: number[];
  rgb: number[];
  isInside: boolean;
  source: string;
}

interface HSVDistributionPlotProps {
  data: any;
  isLoading: boolean;
  error: any;
}

export const HSVDistributionPlot: React.FC<HSVDistributionPlotProps> = ({ data, isLoading, error }) => {
  if (isLoading) {
    return (
      <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-12 flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-8 h-8 animate-spin text-green-600" />
        <p className="text-sm text-neutral-500 font-medium">Calculating HSV Distribution...</p>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-12 flex flex-col items-center justify-center gap-4 text-red-500">
        <AlertCircle className="w-8 h-8" />
        <p className="text-sm font-medium">Failed to load HSV data. Ensure calibration images are assigned.</p>
      </div>
    );
  }

  const { dataset_debug_info, multivariate_color_profile } = data;

  // Helper: HSV to Cartesian (Cylindrical Projection)
  // Matching Tkinter logic: X = S * cos(H_rad), Y = S * sin(H_rad), Z = V
  const toCartesian = (h: number, s: number, v: number) => {
    // OpenCV Hue is 0-179 => 0-360 degrees => Radians
    const h_rad = h * (2 * Math.PI / 180.0);
    const x = s * Math.cos(h_rad);
    const y = s * Math.sin(h_rad);
    const z = v;
    return { x, y, z };
  };

  const allPoints: any[] = [];
  dataset_debug_info.forEach((item: any) => {
    const filename = item.path.split(/[\\/]/).pop();

    item.hsv_colors.forEach((hsv: number[], idx: number) => {
      // Python BGR -> RGB
      const bgr = item.bgr_colors[idx];
      const rgb = [bgr[2], bgr[1], bgr[0]];
      const isOutlier = item.outlier_mask?.[idx] || false;

      const { x, y, z } = toCartesian(hsv[0], hsv[1], hsv[2]);

      allPoints.push({ 
        x, y, z, 
        h: hsv[0], s: hsv[1], v: hsv[2], 
        rgb, 
        isInside: !isOutlier, 
        source: filename 
      });
    });
  });

  const insidePoints = allPoints.filter(p => p.isInside);
  const outsidePoints = allPoints.filter(p => !p.isInside);

  const traceInside: any = {
    x: insidePoints.map(p => p.x),
    y: insidePoints.map(p => p.y),
    z: insidePoints.map(p => p.z),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Inliers (Support)',
    hovertext: insidePoints.map(p => `Image: ${p.source}`),
    hovertemplate: '<b>%{hovertext}</b><br>H: %{customdata[0]:.1f}<br>S: %{customdata[1]:.1f}<br>V: %{customdata[2]:.1f}<extra></extra>',
    customdata: insidePoints.map(p => [p.h, p.s, p.v]),
    marker: {
      size: 3, // Matches Tkinter size
      color: insidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      opacity: 0.6
    }
  };

  const traceOutside: any = {
    x: outsidePoints.map(p => p.x),
    y: outsidePoints.map(p => p.y),
    z: outsidePoints.map(p => p.z),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Outliers',
    hovertext: outsidePoints.map(p => `Image: ${p.source}`),
    hovertemplate: '<b>%{hovertext}</b><br><span style="color:red">OUTLIER</span><br>H: %{customdata[0]:.1f}<br>S: %{customdata[1]:.1f}<br>V: %{customdata[2]:.1f}<extra></extra>',
    customdata: outsidePoints.map(p => [p.h, p.s, p.v]),
    marker: {
      size: 3, // Matches Tkinter size
      // Removed 'x' symbol to match Tkinter style
      color: outsidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      opacity: 0.8
    }
  };

  // --- ELLIPSOID SURFACE GENERATION ---
  // Replicating Tkinter's parametric sphere transformation logic
  const surfaceTraces: any[] = [];
  if (multivariate_color_profile?.transform_matrix) {
    try {
      const centroid = multivariate_color_profile.centroid; // [x, y, z]
      const M = multivariate_color_profile.transform_matrix; // 3x3 matrix

      const resolution = 40; // 40x40 grid like Tkinter
      const xGrid: number[][] = [];
      const yGrid: number[][] = [];
      const zGrid: number[][] = [];

      for (let i = 0; i < resolution; i++) {
        const phi = (i / (resolution - 1)) * 2 * Math.PI; // 0..2PI
        const xRow: number[] = [];
        const yRow: number[] = [];
        const zRow: number[] = [];

        for (let j = 0; j < resolution; j++) {
          const theta = (j / (resolution - 1)) * Math.PI; // 0..PI

          // Parametric Sphere
          const xs = Math.cos(phi) * Math.sin(theta);
          const ys = Math.sin(phi) * Math.sin(theta);
          const zs = Math.cos(theta);

          // Transform: X_ell = X_sphere @ M.T + Centroid
          // Note: In JS, arrays are row-major, but logic is dot product.
          // Point P=[xs, ys, zs]. M=[[m00,m01,m02], ...].
          // Result = P dot M_transposed + C

          const tx = (xs * M[0][0]) + (ys * M[0][1]) + (zs * M[0][2]) + centroid[0];
          const ty = (xs * M[1][0]) + (ys * M[1][1]) + (zs * M[1][2]) + centroid[1];
          const tz = (xs * M[2][0]) + (ys * M[2][1]) + (zs * M[2][2]) + centroid[2];

          xRow.push(tx);
          yRow.push(ty);
          zRow.push(tz);
        }
        xGrid.push(xRow);
        yGrid.push(yRow);
        zGrid.push(zRow);
      }

      surfaceTraces.push({
        type: 'surface',
        x: xGrid,
        y: yGrid,
        z: zGrid,
        opacity: 0.2, // Matches Tkinter
        colorscale: 'Blues',
        showscale: false,
        name: 'Confidence Ellipsoid (97.5%)',
        hoverinfo: 'skip'
      });

    } catch (e) {
      console.warn("Ellipsoid visualization failed", e);
    }
  }

  return (
    <div className="bg-neutral-900 border border-neutral-800 rounded-2xl overflow-hidden p-4 animate-in fade-in zoom-in-95 duration-500">
      <div className="flex items-center justify-between mb-4 px-2">
        <div>
          <h3 className="text-lg font-bold text-white">Multivariate Color Profile</h3>
          <p className="text-[10px] text-neutral-500 uppercase tracking-widest font-bold">
            Cartesian Projection (S·cosH, S·sinH, V)
          </p>
        </div>
        {/* Simple Legend */}
        <div className="flex gap-4 text-[10px] font-bold">
          <div className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full bg-cyan-500 opacity-50"></div>
            <span className="text-neutral-400">ELLIPSOID</span>
          </div>
        </div>
      </div>

      <div className="w-full h-[600px]">
        <Plot
          data={[traceInside, traceOutside, ...surfaceTraces]}
          layout={{
            autosize: true,
            title: '',
            paper_bgcolor: 'rgba(0,0,0,0)',
            plot_bgcolor: 'rgba(0,0,0,0)',
            margin: { l: 0, r: 0, b: 0, t: 0 },
            scene: {
              xaxis: { title: { text: 'X (S * cos H)' }, color: '#737373', gridcolor: '#262626' },
              yaxis: { title: { text: 'Y (S * sin H)' }, color: '#737373', gridcolor: '#262626' },
              zaxis: { title: { text: 'Z (Value)' }, color: '#737373', gridcolor: '#262626' },
              bgcolor: 'rgba(0,0,0,0)',
              aspectmode: 'data' // Important for true shape
            },
            legend: {
              font: { color: '#a3a3a3', size: 10 },
              bgcolor: 'rgba(0,0,0,0.5)',
              x: 0, y: 1
            }
          }}
          style={{ width: '100%', height: '100%' }}
          config={{ displayModeBar: true, responsive: true }}
        />
      </div>
    </div>
  );
};

